"""A Level Physics (Upper Sixth): practice sets for Gravitational Fields & Capacitance; Magnetic Fields,
Electromagnetic Induction & AC Circuits; Mechanical Properties of Matter & Fluid Mechanics (one per lesson)."""

from .dsl import *  # noqa: F403

