M1 = "Gravitational Fields & Capacitance"
M2 = "Magnetic Fields, Electromagnetic Induction & AC Circuits"
M3 = "Mechanical Properties of Matter & Fluid Mechanics"

SETS = []


def Q(prompt, opts, ans, whys, steps, concept, skill, hint, feedback="", diagram="", diagram_alt=""):
    """Four-option MC: opts (4 strings), ans (0-3 index of the correct option), whys (the 3 reasons for the wrong
    options in order, or 4 strings with an empty entry for the correct one)."""
    whys = list(whys)
    if len(whys) == 3:
        whys.insert(ans, "")
    cs = [C(o, correct=(i == ans), why="" if i == ans else whys[i]) for i, o in enumerate(opts)]
    return MC(prompt, cs, steps=steps, concept=concept, skill=skill, hint=hint, feedback=feedback,
              diagram=diagram, diagram_alt=diagram_alt)


